def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    wall = max((v for v in counts if v != bg), key=lambda v: counts[v])
    out = [row[:] for row in grid]

    # Paint nested rectangular bands. Seed colors at a given depth determine
    # that band; unmarked depths default to the background.
    def paint(r0, r1, c0, c1, paint_r0, paint_r1, paint_c0, paint_c1):
        seeds = {}
        for r in range(paint_r0, paint_r1 + 1):
            for c in range(paint_c0, paint_c1 + 1):
                v = grid[r][c]
                if v != bg and v != wall:
                    d = min(r-r0, r1-r, c-c0, c1-c)
                    seeds.setdefault(d, []).append(v)
        if not seeds:
            return
        period = max(seeds) + 1
        bands = [
            Counter(seeds[d]).most_common(1)[0][0] if d in seeds else bg
            for d in range(period)
        ]
        for r in range(paint_r0, paint_r1 + 1):
            for c in range(paint_c0, paint_c1 + 1):
                if grid[r][c] == wall:
                    continue
                d = min(r-r0, r1-r, c-c0, c1-c)
                out[r][c] = bands[d % period]

    # The full-width wall divides off the top rectangular region.
    separators = [r for r in range(h) if all(grid[r][c] == wall for c in range(w))]
    if not separators:
        return out
    sep = separators[0]
    paint(0, sep-1, 0, w-1, 0, sep-1, 0, w-1)

    # Locate a rectangular wall frame enclosing a non-wall colored seed.
    frame = None
    best_area = None
    for r0 in range(sep, h):
        for r1 in range(r0 + 2, h):
            for c0 in range(w):
                for c1 in range(c0 + 2, w):
                    if not (all(grid[r0][c] == wall and grid[r1][c] == wall
                                for c in range(c0, c1+1)) and
                            all(grid[r][c0] == wall and grid[r][c1] == wall
                                for r in range(r0, r1+1))):
                        continue
                    if not any(grid[r][c] not in (bg, wall)
                               for r in range(r0+1, r1)
                               for c in range(c0+1, c1)):
                        continue
                    area = (r1-r0+1) * (c1-c0+1)
                    if best_area is None or area < best_area:
                        frame, best_area = (r0, r1, c0, c1), area

    if frame:
        r0, r1, c0, c1 = frame
        paint(r0, r1, c0, c1, r0+1, r1-1, c0+1, c1-1)

        # Color the rectangular region beyond the frame's right side.
        if c1 < w-1:
            paint(sep, h-1, c1, w-1, sep+1, h-1, c1+1, w-1)

    return out
